-- Name: events shard_distribution_dispatch_trigger; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER shard_distribution_dispatch_trigger AFTER UPDATE OF status ON public.events FOR EACH ROW WHEN ((new.status = 'ended'::public.event_status)) EXECUTE FUNCTION public.dispatch_shard_distribution();


